    private val coroutineScope = CoroutineScope(Dispatchers.IO + SupervisorJob())

    interface NetworkCallback {
        fun onSuccess(response: String)
        fun onError(error: String)
    }

    /**
     * Execute command using coroutines with structured concurrency
     */
    fun executeCommand(ip: String, port: Int, command: String, callback: NetworkCallback) {
        coroutineScope.launch {
            try {
                val result = withTimeout(30000) { // 30 second timeout
                    performNetworkOperation(ip, port, command)
                }

                // Switch to main thread for callback
                withContext(Dispatchers.Main) {
                    callback.onSuccess(result)
                }

            } catch (e: TimeoutCancellationException) {
                withContext(Dispatchers.Main) {
                    callback.onError("Command timed out after 30 seconds")
                }
            } catch (e: Exception) {
                withContext(Dispatchers.Main) {
                    callback.onError("Network error: ${e.message}")
                }
            }
        }
    }

    /**
     * Execute multiple commands in parallel
     */
    fun executeCommandsParallel(ip: String, port: Int, commands: List<String>, 
                                callback: NetworkCallback) {
        coroutineScope.launch {
            try {
                val results = commands.map { command ->
                    async {
                        performNetworkOperation(ip, port, command)
                    }
                }

                val allResults = results.awaitAll()

                withContext(Dispatchers.Main) {
                    callback.onSuccess("All ${commands.size} commands executed successfully")
                }

            } catch (e: Exception) {
                withContext(Dispatchers.Main) {
                    callback.onError("Error executing commands: ${e.message}")
                }
            }
        }
    }

    /**
     * Execute command with retry logic
     */
    fun executeCommandWithRetry(ip: String, port: Int, command: String, 
                                maxRetries: Int = 3, callback: NetworkCallback) {
        coroutineScope.launch {
            var retryCount = 0
            var lastError: Exception? = null

            while (retryCount < maxRetries) {
                try {
                    val result = performNetworkOperation(ip, port, command)

                    withContext(Dispatchers.Main) {
                        callback.onSuccess(result)
                    }
                    return@launch

                } catch (e: Exception) {
                    lastError = e
                    retryCount++

                    if (retryCount < maxRetries) {
                        delay(1000 * retryCount) // Exponential backoff
                    }
                }
            }

            withContext(Dispatchers.Main) {
                callback.onError("Failed after $maxRetries attempts: ${lastError?.message}")
            }
        }
    }

    private suspend fun performNetworkOperation(ip: String, port: Int, command: String): String {
        return withContext(Dispatchers.IO) {
