func NewBudgetOptimizer(categories []string, minWeights, maxWeights []float64, totalBudget float64) *BudgetOptimizer {
    // First, check that our inputs make sense
    if len(categories) != len(minWeights) || len(categories) != len(maxWeights) {
        panic("All input arrays must have the same length")
    }

    for i := range minWeights {
        if minWeights[i] > maxWeights[i] {
            panic(fmt.Sprintf("Minimum cannot exceed maximum for category %d", i))
        }
    }

    // Create realistic performance estimates for each category
    // In a real application, this would come from historical data
    expectedReturns := make([]float64, len(categories))
    riskFactors := make([]float64, len(categories))

    for i := range categories {
        // Categories with wider allocation ranges typically offer higher returns but with more risk
        rangeSize := maxWeights[i] - minWeights[i]
        expectedReturns[i] = 0.05 + rangeSize*0.3  // 5-35% expected return
        riskFactors[i] = 0.02 + rangeSize*0.5      // 2-52% risk factor
    }

    // Return our fully configured optimizer with sensible defaults
    return &BudgetOptimizer{
        Categories:      categories,
        MinWeights:      minWeights,
        MaxWeights:      maxWeights,
        TotalBudget:     totalBudget,
        PopulationSize:  100,    // Start with 100 different plans
        MutationRate:    0.15,   // 15% chance of random changes
        CrossoverRate:   0.85,   // 85% chance of combining plans
        Generations:     200,    // Run 200 improvement cycles
        ElitismCount:    2,      // Keep 2 best plans each generation
        TournamentSize:  3,      // Compare 3 plans when selecting
        ExpectedReturns: expectedReturns,
        RiskFactors:     riskFactors,
    }
}

