    std::string computeDescriptorId(const std::string& onion_address, uint64_t revision = 0) {
        // Remove .onion suffix if present
        std::string clean_address = onion_address;
        if (clean_address.size() > 6 && clean_address.substr(clean_address.size() - 6) == ".onion") {
            clean_address = clean_address.substr(0, clean_address.size() - 6);
        }

        // HSv3 descriptor-id = SHA3-256("hs-descriptor" || onion_address || revision-counter)
        std::vector<unsigned char> data;
        std::string prefix = "hs-descriptor";

        data.insert(data.end(), prefix.begin(), prefix.end());
        data.insert(data.end(), clean_address.begin(), clean_address.end());

        // Add revision counter (big-endian)
        for (int i = 7; i >= 0; i--) {
            data.push_back((revision >> (i * 8)) & 0xFF);
        }

        // First SHA3-256
        std::vector<unsigned char> hash1(32);
        EVP_MD_CTX* ctx = EVP_MD_CTX_new();
        EVP_DigestInit_ex(ctx, EVP_sha3_256(), NULL);
        EVP_DigestUpdate(ctx, data.data(), data.size());
        EVP_DigestFinal_ex(ctx, hash1.data(), NULL);
        EVP_MD_CTX_free(ctx);

        // Second SHA3-256
        std::vector<unsigned char> hash2(32);
        ctx = EVP_MD_CTX_new();
        EVP_DigestInit_ex(ctx, EVP_sha3_256(), NULL);
        EVP_DigestUpdate(ctx, hash1.data(), hash1.size());
        EVP_DigestFinal_ex(ctx, hash2.data(), NULL);
        EVP_MD_CTX_free(ctx);

        // Base32 encoding (first 32 bytes)
        return base32Encode(std::string(hash2.begin(), hash2.begin() + 32));
    }

    std::string base32Encode(const std::string& data) {
        const char alphabet[] = "abcdefghijklmnopqrstuvwxyz234567";
        std::string encoded;
        int buffer = 0;
        int bits = 0;

        for (unsigned char c : data) {
            buffer = (buffer << 8) | c;
            bits += 8;

            while (bits >= 5) {
                bits -= 5;
                encoded += alphabet[(buffer >> bits) & 31];
            }
        }

        if (bits > 0) {
            encoded += alphabet[(buffer << (5 - bits)) & 31];
        }

        return encoded;
    }

