        """Get magical properties of ingredients from various sources"""
        properties = {
            'name': ingredient,
            'magical_properties': [],
            'historical_uses': [],
            'elemental_association': None,
            'source': None
        }

        try:
            # Try Wikipedia first
            wiki_data = self._search_wikipedia(ingredient)
            if wiki_data:
                properties['historical_uses'].extend(wiki_data.get('uses', []))
                properties['source'] = 'Wikipedia'

            # Try magical herb databases
            magical_props = self._search_magical_database(ingredient)
            if magical_props:
                properties['magical_properties'].extend(magical_props)
                properties['source'] = 'Magical Database'

            # Use AI as fallback
            if not properties['magical_properties']:
                ai_props = self._get_ai_magical_properties(ingredient)
                properties['magical_properties'].extend(ai_props)
                properties['source'] = 'AI Generation'

        except Exception as e:
            print(f"Error getting properties for {ingredient}: {e}")

        return properties

    def _search_wikipedia(self, ingredient: str) -> Optional[Dict]:
        """Search Wikipedia for ingredient information"""
        try:
            params = {
                'action': 'query',
                'format': 'json',
                'list': 'search',
                'srsearch': f"{ingredient} magical properties OR historical uses",
                'utf8': 1,
                'srlimit': 3
            }

            response = requests.get(WIKIPEDIA_API_URL, params=params, timeout=10)
            data = response.json()

            if data.get('query', {}).get('search'):
                return {
                    'uses': [result['snippet'] for result in data['query']['search'][:2]]
                }
        except:
