    % Compute lift coefficient
    chord = max(x_points) - min(x_points);
    Cl = 2 * gamma / (V_inf * chord);

    % Compute analytical results
    [Cl_theory, Cp_theory, x_theory] = compute_analytical_results(alpha_deg, airfoil_name, n_panels);

    % Display comprehensive results
    display_results(Cl, gamma, Cl_theory, exp_data, alpha_deg);

    % Plot results with experimental comparison
    plot_results_with_comparison(panels, x_points, y_points, Cp, V_inf, ...
                                alpha_deg, source_strengths, gamma, ...
                                exp_data, Cl_theory, Cp_theory, x_theory);
