        # Group by submission date (daily)
        photos = query.order_by(Photo.submitted_at.asc()).all()

        # Group by date
        date_groups = {}
        for photo in photos:
            date_str = photo.submitted_at.date().isoformat()
            if date_str not in date_groups:
                date_groups[date_str] = []
            date_groups[date_str].append(photo)

        grouped_results = []
        for date_str in sorted(date_groups.keys()):
            group_photos = date_groups[date_str]
            grouped_results.append({
                'group_key': date_str,
                'photos': [
                    {
                        'id': p.id,
                        'name': p.name,
                        'price': p.price,
                        'description': p.description,
                        'filename': p.filename,
                        'image_url': f'/api/photos/image/{p.filename}'
                    }
                    for p in group_photos
                ],
                'count': len(group_photos)
            })

    # Apply final sorting to groups
    if sort_by == 'price':
        if group_by == 'name':
            grouped_results.sort(key=lambda x: x['photo']['price'])
        else:
            grouped_results.sort(key=lambda x: x['avg_price'] if 'avg_price' in x else 0)

    elif sort_by == 'name':
        grouped_results.sort(key=lambda x: x['group_key'].lower())

    elif sort_by == 'description_length':
        if group_by == 'name':
            grouped_results.sort(key=lambda x: len(x['photo']['description'] or ''))

    # Calculate statistics if requested
    stats = {}
    if show_stats:
        all_photos = query.all()
        if all_photos:
            prices = [p.price for p in all_photos]
            stats = {
                'total_photos': len(all_photos),
                'average_price': sum(prices) / len(prices),
                'min_price': min(prices),
                'max_price': max(prices),
                'price_range': max(prices) - min(prices),
                'unique_names': len(set(p.name for p in all_photos))
            }

    return jsonify({
        'comparison_view': grouped_results,
        'grouped_by': group_by,
        'sorted_by': sort_by,
        'statistics': stats if show_stats else None,
        'total_groups': len(grouped_results)
    })

