@app.route('/api/photos/search/suggestions', methods=['GET'])
def get_search_suggestions():
    """
    Get search suggestions based on photo names and descriptions
    """
    search_prefix = request.args.get('q', '').strip().lower()

    if not search_prefix or len(search_prefix) < 2:
        return jsonify({'suggestions': []})

    # Search in names
    name_suggestions = Photo.query.filter(
        Photo.name.ilike(f'{search_prefix}%'),
        Photo.is_active == True,
        Photo.status == 'approved'
    ).with_entities(Photo.name).distinct().limit(10).all()

    # Search in descriptions for keywords
    description_keywords = Photo.query.filter(
        Photo.description.ilike(f'%{search_prefix}%'),
        Photo.is_active == True,
        Photo.status == 'approved'
    ).with_entities(Photo.description).limit(10).all()

    suggestions = []

    # Add name suggestions
    for name_tuple in name_suggestions:
        suggestions.append({
            'type': 'name',
            'value': name_tuple[0],
            'display': f"Name: {name_tuple[0]}"
        })

    # Extract keywords from descriptions
    keyword_set = set()
    for desc_tuple in description_keywords:
        if desc_tuple[0]:
            words = desc_tuple[0].lower().split()
            for word in words:
                if word.startswith(search_prefix) and len(word) > 2:
                    keyword_set.add(word)

    for keyword in list(keyword_set)[:10]:  # Limit to 10 keywords
        suggestions.append({
            'type': 'keyword',
            'value': keyword,
            'display': f"Keyword: {keyword}"
        })

    return jsonify({
        'suggestions': suggestions[:20],  # Total limit
        'query': search_prefix,
        'total_suggestions': len(suggestions)
    })

