# terrain_chunk_controller.py
# Python script for Unity Editor - helps manage Vista 2023 asset integration
# and generates configuration for the C# runtime system

import json
import os
from typing import List, Dict, Tuple
import math

class TerrainChunkConfigGenerator:
    """
    Python helper class to generate configuration for the C# terrain chunk system.
    This works with the Vista 2023 asset from Unity Store.
    """

    def __init__(self, vista_asset_path: str = "Assets/Vista 2023"):
        self.vista_path = vista_asset_path
        self.chunk_size = 100  # Size of each terrain chunk
        self.render_distance = 3  # Chunks in each direction from player
        self.max_chunks_in_memory = 50

    def generate_chunk_layout(self) -> Dict:
        """
        Generate the chunk coordinate layout based on render distance.
        Returns a dictionary with chunk positions and their LOD levels.
        """
        layout = {}
        for x in range(-self.render_distance, self.render_distance + 1):
            for z in range(-self.render_distance, self.render_distance + 1):
                distance = math.sqrt(x**2 + z**2)
                # Determine LOD based on distance from center
                if distance <= 1:
                    lod = 0  # Highest detail
                elif distance <= 2:
                    lod = 1
                else:
                    lod = 2
                layout[f"{x},{z}"] = {
                    "position": [x * self.chunk_size, 0, z * self.chunk_size],
                    "lod": lod,
                    "size": self.chunk_size
                }
        return layout

    def create_vista_material_config(self) -> Dict:
        """
        Create material configuration compatible with Vista 2023 shaders.
        """
        return {
            "shader": "Vista/StandardTerrain",
            "textures": {
                "albedo": f"{self.vista_path}/Textures/TerrainAlbedo.png",
                "normal": f"{self.vista_path}/Textures/TerrainNormal.png",
                "height": f"{self.vista_path}/Textures/TerrainHeight.png"
            },
            "tiling": 4.0
        }

    def generate_config_file(self, output_path: str = "Assets/Resources/TerrainConfig.json"):
        """
        Generate JSON configuration file for the C# system.
        """
        config = {
            "chunk_size": self.chunk_size,
            "render_distance": self.render_distance,
            "max_chunks": self.max_chunks_in_memory,
            "chunk_layout": self.generate_chunk_layout(),
            "vista_materials": self.create_vista_material_config(),
            "async_generation": True,
            "collision_enabled": True
        }

        os.makedirs(os.path.dirname(output_path), exist_ok=True)
        with open(output_path, 'w') as f:
            json.dump(config, f, indent=2)

        print(f"Configuration generated at: {output_path}")
        return config

# Editor integration helper
if __name__ == "__main__":
