            chunkSize = loadedConfig.chunk_size;
            renderDistance = loadedConfig.render_distance;
            maxChunksInMemory = loadedConfig.max_chunks;
            asyncGeneration = loadedConfig.async_generation;
            enableCollision = loadedConfig.collision_enabled;
