            HideChunk(chunkCoord);
        }
    }

    IEnumerator GenerateChunkAsync(Vector2Int chunkCoord)
    {
        if (loadedChunks.ContainsKey(chunkCoord) && loadedChunks[chunkCoord].isGenerating)
            yield break;

        // Create new chunk data
        ChunkData chunkData = new ChunkData
        {
            position = new Vector3(chunkCoord.x * chunkSize, 0, chunkCoord.y * chunkSize),
            lod = CalculateLOD(chunkCoord, lastPlayerChunkCoord),
            size = chunkSize,
            isLoaded = false,
            isGenerating = true
        };

        if (!loadedChunks.ContainsKey(chunkCoord))
        {
            loadedChunks[chunkCoord] = chunkData;
        }

        // Generate terrain mesh asynchronously
        Task<Mesh> meshTask = Task.Run(() => GenerateProceduralMesh(chunkData), cancellationTokenSource.Token);

        while (!meshTask.IsCompleted)
        {
            yield return null;
        }

        if (meshTask.IsCompletedSuccessfully)
        {
            // Create GameObject for the chunk
            GameObject chunkObject = new GameObject($"TerrainChunk_{chunkCoord.x}_{chunkCoord.y}");
            chunkObject.transform.position = chunkData.position;
            chunkObject.transform.SetParent(transform);

            // Add mesh components
            MeshFilter meshFilter = chunkObject.AddComponent<MeshFilter>();
            MeshRenderer meshRenderer = chunkObject.AddComponent<MeshRenderer>();
            MeshCollider meshCollider = null;

            if (enableCollision)
            {
                meshCollider = chunkObject.AddComponent<MeshCollider>();
            }

            // Apply generated mesh
            meshFilter.mesh = meshTask.Result;
            meshRenderer.material = terrainMaterial;

            if (enableCollision && meshCollider != null)
            {
                meshCollider.sharedMesh = meshTask.Result;
            }

            // Update chunk data
            chunkData.chunkObject = chunkObject;
            chunkData.isLoaded = true;
            chunkData.isGenerating = false;
            loadedChunks[chunkCoord] = chunkData;

            Debug.Log($"Chunk generated at {chunkCoord}");
        }
        else
        {
            Debug.LogError($"Failed to generate chunk at {chunkCoord}");
            chunkData.isGenerating = false;
        }
    }

    Mesh GenerateProceduralMesh(ChunkData chunkData)
    {
        // This is where you'd implement your procedural generation algorithm
        // For Vista 2023 integration, you might use their terrain generation API

        int resolution = 32 * (4 - chunkData.lod); // Higher LOD = lower resolution
        Mesh mesh = new Mesh();

        List<Vector3> vertices = new List<Vector3>();
        List<int> triangles = new List<int>();
        List<Vector2> uv = new List<Vector2>();

        // Generate grid of vertices
        for (int z = 0; z <= resolution; z++)
        {
            for (int x = 0; x <= resolution; x++)
            {
                float xPos = (float)x / resolution * chunkData.size;
                float zPos = (float)z / resolution * chunkData.size;

                // Sample height from Vista 2023 heightmap or procedural noise
                float yPos = SampleHeight(xPos + chunkData.position.x, zPos + chunkData.position.z);

                vertices.Add(new Vector3(xPos, yPos, zPos));
                uv.Add(new Vector2((float)x / resolution, (float)z / resolution));
            }
        }

        // Generate triangles
        for (int z = 0; z < resolution; z++)
        {
            for (int x = 0; x < resolution; x++)
            {
                int i = (z * (resolution + 1)) + x;

                triangles.Add(i);
                triangles.Add(i + resolution + 1);
                triangles.Add(i + 1);

                triangles.Add(i + 1);
                triangles.Add(i + resolution + 1);
                triangles.Add(i + resolution + 2);
            }
        }

        mesh.vertices = vertices.ToArray();
        mesh.triangles = triangles.ToArray();
        mesh.uv = uv.ToArray();
        mesh.RecalculateNormals();
        mesh.RecalculateBounds();

        return mesh;
    }

    float SampleHeight(float worldX, float worldZ)
    {
        // Implement your height sampling logic here
        // This could use Vista 2023's heightmap sampling or procedural noise
        // Example using Perlin noise:
        float scale = 0.1f;
        float heightScale = 50f;
        return Mathf.PerlinNoise(worldX * scale, worldZ * scale) * heightScale;
    }

    int CalculateLOD(Vector2Int chunkCoord, Vector2Int playerChunkCoord)
    {
        float distance = Vector2Int.Distance(chunkCoord, playerChunkCoord);

        if (distance <= 1) return 0;
        if (distance <= 2) return 1;
        if (distance <= 3) return 2;
        return 3;
    }

    void HideChunk(Vector2Int chunkCoord)
    {
        if (loadedChunks.ContainsKey(chunkCoord) && loadedChunks[chunkCoord].chunkObject != null)
        {
            loadedChunks[chunkCoord].chunkObject.SetActive(false);
        }
    }

    void UnloadDistantChunks(Vector2Int centerChunk)
    {
        List<Vector2Int> chunksToUnload = new List<Vector2Int>();

        foreach (var chunk in loadedChunks)
        {
            float distance = Vector2Int.Distance(chunk.Key, centerChunk);
            if (distance > renderDistance * 1.5f) // Unload chunks beyond 1.5x render distance
            {
                chunksToUnload.Add(chunk.Key);
            }
        }

        foreach (var chunkCoord in chunksToUnload)
        {
            if (loadedChunks.ContainsKey(chunkCoord) && loadedChunks[chunkCoord].chunkObject != null)
            {
                Destroy(loadedChunks[chunkCoord].chunkObject);
                loadedChunks.Remove(chunkCoord);
            }
        }
    }

    void OnDestroy()
    {
        // Clean up async operations
        if (cancellationTokenSource != null)
        {
            cancellationTokenSource.Cancel();
            cancellationTokenSource.Dispose();
        }
    }

    void OnDrawGizmosSelected()
    {
        // Visualize chunk boundaries in editor
        Gizmos.color = Color.green;
        foreach (var chunk in loadedChunks.Values)
        {
            if (chunk.isLoaded && chunk.chunkObject != null)
            {
                Gizmos.DrawWireCube(
                    chunk.position + new Vector3(chunk.size / 2, 0, chunk.size / 2),
                    new Vector3(chunk.size, 1, chunk.size)
                );
            }
        }
    }
}
```

## Implementation Explanation

### Key Features:

1. **Asynchronous Chunk Generation**: Uses C# Tasks and coroutines to generate terrain chunks without blocking the main thread.

2. **Dynamic Loading/Unloading**: 
   - Only generates chunks within the player's render distance
   - Unloads chunks that are too far away (beyond 1.5x render distance)
   - Implements a chunk generation queue for orderly processing

3. **Vista 2023 Integration**:
   - Configures materials with Vista 2023 shaders and textures
   - Supports heightmap sampling from Vista assets
   - Material setup for terrain rendering

4. **LOD System**: Implements Level of Detail based on distance from player:
   - LOD 0: Highest detail (closest)
   - LOD 1-3: Decreasing detail with distance

5. **Memory Management**: 
   - Limits maximum chunks in memory
   - Efficient unloading of distant chunks
   - Configurable through JSON settings

### Usage:

1. **Python Script**: Run in Unity Editor to generate configuration
2. **C# Script**: Attach to a GameObject in your scene
3. **Configuration**: Modify `TerrainConfig.json` to adjust settings
4. **Vista 2023 Assets**: Ensure Vista 2023 package is imported and textures are assigned

### Customization Points:

1. **Procedural Generation**: Modify `GenerateProceduralMesh()` and `SampleHeight()` methods
2. **Chunk Size**: Adjust `chunkSize` variable for different terrain scales
3. **Render Distance**: Change `renderDistance` for performance/quality balance
4. **LOD System**: Modify `CalculateLOD()` for different detail levels

This system provides a foundation for infinite procedural terrain with Vista 2023 integration, with room for optimization and feature expansion based on specific project needs.

