public class PredictiveChunkLoader : MonoBehaviour
{
    public TerrainChunkController terrainController;
    public Transform player;
    public float predictionDistance = 50f;
    public int predictionSteps = 3;

    private Vector3 lastPosition;
    private Vector3 velocity;
    private Queue<Vector2Int> predictedChunks = new Queue<Vector2Int>();

    void Update()
    {
        // Calculate player velocity
        velocity = (player.position - lastPosition) / Time.deltaTime;
        lastPosition = player.position;

        // Predict future positions
        PredictFutureChunks();

        // Pre-load predicted chunks
        PreloadPredictedChunks();
    }

    void PredictFutureChunks()
    {
        predictedChunks.Clear();

        Vector3 currentPos = player.position;
        Vector3 predictedPos = currentPos;

        for (int i = 1; i <= predictionSteps; i++)
        {
            predictedPos += velocity * (i * 0.5f); // Predict 0.5s, 1.0s, 1.5s ahead

            Vector2Int chunkCoord = terrainController.GetChunkCoordinate(predictedPos);
            if (!predictedChunks.Contains(chunkCoord))
            {
                predictedChunks.Enqueue(chunkCoord);
            }
        }
    }

    void PreloadPredictedChunks()
    {
        while (predictedChunks.Count > 0)
        {
            Vector2Int chunkCoord = predictedChunks.Dequeue();

            // Check if chunk needs to be loaded
            if (!terrainController.IsChunkLoaded(chunkCoord) && 
                !terrainController.IsChunkGenerating(chunkCoord))
            {
                terrainController.QueueChunkForGeneration(chunkCoord, priority: 1);
            }
        }
    }
