        ### 1.2 Memory Management for Large Terrains
        **Challenge**: Vista 2023 materials and terrain data can consume significant memory
        when generating large-scale procedural worlds.

        **Solutions**:
        ```
        // VistaMemoryManager.cs
        using System.Collections.Generic;
        using UnityEngine;
        using System.Linq;

        public class VistaMemoryManager : MonoBehaviour
        {
            [Header("Memory Settings")]
            [SerializeField] private float memoryBudgetMB = 1024f;
            [SerializeField] private float warningThreshold = 0.8f; // 80% of budget
            [SerializeField] private bool enableTextureStreaming = true;
            [SerializeField] private bool compressTerrainData = true;

            private float currentMemoryUsage;
            private List<Texture2D> loadedTextures = new List<Texture2D>();
            private Dictionary<Vector2Int, TerrainData> terrainDataCache = new Dictionary<Vector2Int, TerrainData>();

            void Update()
            {
                MonitorMemoryUsage();
                EnforceMemoryBudget();
            }

            void MonitorMemoryUsage()
            {
                // Calculate current memory usage
                currentMemoryUsage = CalculateTextureMemory() + CalculateTerrainDataMemory();

                // Log warning if approaching budget
                if (currentMemoryUsage > memoryBudgetMB * warningThreshold)
                {
                    Debug.LogWarning($"Memory usage high: {currentMemoryUsage:F1}MB / {memoryBudgetMB}MB");
                    TriggerMemoryOptimization();
                }
            }

            float CalculateTextureMemory()
            {
                float total = 0f;
                foreach (var tex in loadedTextures)
                {
                    if (tex != null)
                    {
                        // Estimate texture memory (width * height * bytes per pixel)
                        total += (tex.width * tex.height * 4) / (1024f * 1024f);
                    }
                }
                return total;
            }

            float CalculateTerrainDataMemory()
            {
                float total = 0f;
                foreach (var terrainData in terrainDataCache.Values)
                {
                    if (terrainData != null)
                    {
                        // Estimate terrain data memory
                        total += terrainData.heightmapResolution * terrainData.heightmapResolution * 2 / (1024f * 1024f);
                    }
                }
                return total;
            }

            void EnforceMemoryBudget()
            {
                if (currentMemoryUsage <= memoryBudgetMB) return;

                // Unload least recently used textures
                UnloadLRUTextures();

                // Unload distant terrain data
                UnloadDistantTerrainData();

                // Force garbage collection
                System.GC.Collect();
            }

            void TriggerMemoryOptimization()
            {
                // Reduce texture quality for distant chunks
                ReduceTextureQualityForDistantChunks();

                // Enable texture compression if not already
                if (compressTerrainData)
                {
                    CompressTerrainData();
                }
            }

            public void RegisterTexture(Texture2D texture, int priority = 0)
            {
                if (texture == null) return;

                loadedTextures.Add(texture);

                // Apply texture streaming if enabled
                if (enableTextureStreaming)
                {
                    texture.requestedMipMapLevel = priority > 0 ? 1 : 0;
                }
            }

            public void UnloadTexture(Texture2D texture)
            {
                if (texture != null)
                {
                    Resources.UnloadAsset(texture);
                    loadedTextures.Remove(texture);
                }
            }

            void UnloadLRUTextures()
            {
                // Sort textures by last access time (simplified)
                var texturesToUnload = loadedTextures
                    .Where(t => t != null)
                    .OrderBy(t => t.GetInstanceID() % 100) // Simplified LRU simulation
                    .Take(loadedTextures.Count / 4) // Unload 25%
                    .ToList();

                foreach (var texture in texturesToUnload)
                {
                    UnloadTexture(texture);
                }
            }

            void ReduceTextureQualityForDistantChunks()
            {
                // Reduce mipmap levels for textures used by distant chunks
                foreach (var texture in loadedTextures)
                {
                    if (texture != null && texture.mipmapCount > 1)
                    {
                        texture.requestedMipMapLevel = Mathf.Min(texture.mipmapCount - 1, 2);
                    }
                }
            }
        }
