            materialSettings.terrainMaterial = Resources.Load<Material>("Vista/Materials/StandardTerrain");
            materialSettings.enableTriplanarMapping = true;
            materialSettings.normalStrength = 1.0f;
            materialSettings.smoothness = 0.5f;

            // Setup texture arrays for blending
            materialSettings.albedoTextures = LoadVistaTextureArray("Albedo");
