            public async Task<HeightmapData> GenerateOptimizedHeightmap(
                Vector2Int chunkCoord, 
                Vector3 worldPosition
            )
            {
                // Check cache first
                if (cacheHeightmapSamples && heightmapCache.ContainsKey(chunkCoord))
                {
                    return heightmapCache[chunkCoord];
                }

                HeightmapData heightmap;

                if (useGPUHeightmap)
                {
