                heightmapComputeShader.SetTexture(kernelIndex, "Result", heightmapRT);
                heightmapComputeShader.SetVector("WorldPosition", worldPosition);
                heightmapComputeShader.SetFloat("NoiseScale", 100f);

                // Dispatch compute shader
                heightmapComputeShader.Dispatch(
