function prime = generate_large_prime(bits)
    % GENERATE_LARGE_PRIME Generate a large prime number
    %
    % Input:
    %   bits - Approximate bit length of prime
    %
    % Output:
    %   prime - A prime number of approximately 'bits' bits

    % MATLAB's isprime is efficient for large numbers
    % but we need to generate random numbers of specific bit length

    % Calculate approximate decimal range for desired bit length
    min_val = 2^(bits - 1);
    max_val = 2^bits - 1;

    % Generate random odd number in the range
    candidate = randi([min_val, max_val]);

    % Ensure it's odd
    if mod(candidate, 2) == 0
        candidate = candidate + 1;
        if candidate > max_val
            candidate = candidate - 2;
        end
    end

    % Find next prime (MATLAB's isprime is deterministic)
    while ~isprime(candidate)
        candidate = candidate + 2;
        % If we exceed max_val, wrap around
        if candidate > max_val
            candidate = min_val;
            if mod(candidate, 2) == 0
                candidate = candidate + 1;
            end
        end
    end

    prime = candidate;
end

