function prime = generate_prime(bits)
    % Simple prime generation for demonstration
    min_val = 2^(bits-1);
    max_val = 2^bits - 1;

    candidate = randi([min_val, max_val]);
    if mod(candidate, 2) == 0
        candidate = candidate + 1;
    end

    while ~isprime(candidate)
        candidate = candidate + 2;
    end

    prime = candidate;
end

function [g, x, y] = extended_gcd(a, b)
    % Extended Euclidean Algorithm
    if a == 0
        g = b;
        x = 0;
        y = 1;
    else
        [g, x1, y1] = extended_gcd(mod(b, a), a);
        x = y1 - floor(b / a) * x1;
        y = x1;
    end
end
