                    try:
                        start = max(1, int(start_str))
                        end = min(total_pages, int(end_str))
                        if start > end:
                            start, end = end, start
                        page_range = range(start-1, end)
                    except ValueError:
                        page_range = range(total_pages)  # Fallback to all pages
                else:
                    try:
                        page_num = int(pages)
                        page_range = [min(page_num, total_pages) - 1]
                    except ValueError:
                        page_range = range(total_pages)  # Fallback to all pages

                text_data = []
                for page_num in page_range:
                    try:
                        if page_num >= total_pages:
